// The Go side's functions (generated by Wails into src/wailsjs), typed with
// the page's own types.
import * as Go from "../wailsjs/go/main/App"
import { EventsOn } from "../wailsjs/runtime/runtime"
import type { Info, LogDay, LogPage, LogQuery, Settings, Tick, UpdateState } from "./types"

/* eslint-disable @typescript-eslint/no-explicit-any */
const call = <T,>(p: Promise<any>) => p as Promise<T>

export const api = {
    info: () => call<Info>(Go.GetInfo()),
    tick: () => call<Tick>(Go.GetTick()),
    settings: () => call<Settings>(Go.GetSettings()),
    saveSettings: (s: Settings) => call<Settings>(Go.SaveSettings(s as any)),
    searchLogs: (q: LogQuery) => call<LogPage>(Go.SearchLogs(q as any)),
    logDays: () => call<LogDay[]>(Go.LogDays()),
    exportLogs: (q: LogQuery) => call<string>(Go.ExportLogs(q as any)),
    openLogsFolder: () => call<void>(Go.OpenLogsFolder()),
    openURL: (u: string) => call<void>(Go.OpenURL(u)),
    updateGeo: () => call<void>(Go.UpdateGeo()),
    checkForUpdates: () => call<UpdateState>(Go.CheckForUpdates()),
    installUpdate: () => call<void>(Go.InstallUpdate()),
    restartToUpdate: () => call<void>(Go.RestartToUpdate()),
    skipVersion: (v: string) => call<void>(Go.SkipVersion(v)),
}

export function onTick(f: (t: Tick) => void) {
    return EventsOn("tick", f)
}

export function onStatus(f: (s: Pick<Tick, "geo" | "update">) => void) {
    return EventsOn("status", f)
}
